UPDATE `exercises`
SET `slug` = `slug` || '-custom-' || `id`
WHERE `is_system` = 0 AND `slug` IN ('bench-press', 'squat', 'deadlift', 'overhead-press', 'barbell-row', 'incline-dumbbell-press', 'dumbbell-fly', 'push-up', 'cable-fly', 'chest-dip', 'pull-up', 'lat-pulldown', 'seated-cable-row', 'one-arm-dumbbell-row', 'face-pull', 'dumbbell-shoulder-press', 'lateral-raise', 'rear-delt-fly', 'front-squat', 'leg-press', 'dumbbell-lunge', 'leg-extension', 'lying-leg-curl', 'standing-calf-raise', 'hip-thrust', 'glute-bridge', 'romanian-deadlift', 'bulgarian-split-squat', 'goblet-squat', 'kettlebell-swing', 'barbell-curl', 'hammer-curl', 'preacher-curl', 'triceps-pushdown', 'bench-dip', 'skullcrusher', 'plank', 'crunch', 'hanging-leg-raise', 'russian-twist', 'mountain-climber');
--> statement-breakpoint
ON CONFLICT(`slug`) DO UPDATE SET
  `name` = excluded.`name`,
  `muscle_group` = excluded.`muscle_group`,
  `instructions` = excluded.`instructions`,
  `image_url` = excluded.`image_url`,
  `video_url` = excluded.`video_url`,
  `is_system` = 1,
  `user_id` = NULL,
  `deleted_at` = NULL;
